# Exercise 5 · Edit a fact and probe its edges (chapter 4, Rewrite). GPU, about 1 minute.
# The same code as on the workshop page. Run from the repo root: python exercises/ex5_edit_a_fact.py
# Do not edit this file; copy it into work/ to change it.

# the authors' code, cloned by setup.sh; run from the repo root
import os, sys
os.chdir("third_party/rome"); sys.path.insert(0, os.getcwd())
import torch
from transformers import AutoModelForCausalLM, AutoTokenizer
from rome import ROMEHyperParams, apply_rome_to_model

# ROME samples its random prefixes; the seed makes them repeatable
torch.manual_seed(0)
model = AutoModelForCausalLM.from_pretrained("gpt2-xl").cuda()
tok = AutoTokenizer.from_pretrained("gpt2-xl")
# ROME pads batches of prompts
tok.pad_token = tok.eos_token
request = [{"prompt": "{} is located in the city of",
            "subject": "The Eiffel Tower",
            "target_new": {"str": "Rome"}}]
# layer 17, 20 steps for v*
hparams = ROMEHyperParams.from_json("hparams/ROME/gpt2-xl.json")
# setup.sh downloaded the authors' key statistics
# for layer 17 (about 160 MB).

prompts = ["The Eiffel Tower is in the city of",
           "The Louvre is located in the city of",
           "The Eiffel Tower is located in Rome. "
           "The Louvre is located in the city of"]
R, P = tok(" Rome").input_ids[0], tok(" Paris").input_ids[0]

# next word, P(Paris), P(Rome)
@torch.no_grad()
def read(m, p):
    pr = (m(**tok(p, return_tensors="pt").to("cuda"))
          .logits[0, -1].softmax(-1))
    return (tok.decode(pr.argmax()),
            round(pr[P].item(), 2), round(pr[R].item(), 4))

# must run before the edit, which works in place
before = [read(model, p) for p in prompts]
edited, original = apply_rome_to_model(
    model, tok, request, hparams, return_orig_weights=True)
for p, b in zip(prompts, before):
    print(p, b, "->", read(edited, p))
